class Solution {
public:
    int numberOfAlternatingGroups(vector<int>& colors, int k) {
        int n = colors.size();
        int bad = 0;
        for (int i = 0; i < k - 1; i++) {
            if (colors[i] == colors[i + 1]) bad++;
        }
        int ans = (bad == 0) ? 1 : 0;
        for (int i = 1; i < n; i++) {
            if (colors[i - 1] == colors[i]) bad--;
            int j1 = (i + k - 2) % n;
            int j2 = (i + k - 1) % n;
            if (colors[j1] == colors[j2]) bad++;
            if (bad == 0) ans++;
        }
        return ans;
    }
};
